import{_ as a,o as s,c as i,a5 as n}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"79. Code Review Checklist for C Projects","description":"The Little Book of C — 79. Code Review Checklist for C Projects","frontmatter":{"title":"79. Code Review Checklist for C Projects","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Debugging Testing Profiling"],"description":"The Little Book of C — 79. Code Review Checklist for C Projects","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":79,"sidebarWeight":79,"lang":"en-US","alternateEn":"/posts/c教程/en-US/08-Debugging Testing Profiling/079-Code Review Checklist for C Projects","alternateZh":"/posts/c教程/zh-CN/08-调试测试与 profiling/079-Code Review Checklist for C Projects"},"headers":[],"relativePath":"posts/c教程/en-US/08-Debugging Testing Profiling/079-Code Review Checklist for C Projects.md","filePath":"posts/c教程/en-US/08-Debugging Testing Profiling/079-Code Review Checklist for C Projects.md","lastUpdated":1790163617000}'),t={name:"posts/c教程/en-US/08-Debugging Testing Profiling/079-Code Review Checklist for C Projects.md"};function l(o,e,r,p,c,d){return s(),i("div",null,[...e[0]||(e[0]=[n(`<p>[中文版本](/posts/c教程/zh-CN/08-调试测试与 profiling/079-Code Review Checklist for C Projects)</p><p>Before your C program ships to production (or even your homework submission), it should survive one last test, a code review. This is where you or your teammates look at the code not just for correctness, but for clarity, safety, and maintainability.</p><p>Think of this as your personal pilot checklist before takeoff. Every great C programmer has one.</p><h4 id="step-1-readability-and-structure" tabindex="-1">Step 1. Readability and Structure <a class="header-anchor" href="#step-1-readability-and-structure" aria-label="Permalink to &quot;Step 1. Readability and Structure&quot;">​</a></h4><ul><li>Are files organized logically (<code>src/</code>,<code>include/</code>,<code>tests/</code>)?</li><li>Are headers clean, with include guards?</li><li>Are functions short and focused (one purpose each)?</li><li>Are names meaningful (<code>count_users()</code> is better than<code>doit()</code>)?</li><li>Is indentation consistent and readable?</li><li>Are comments clear and relevant, not just noise?</li></ul><p>Tiny Code Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Bad</span></span>
<span class="line"><span>void d(int a, int b) { printf(&quot;%d\\n&quot;, a+b); }</span></span>
<span class="line"><span>// Good</span></span>
<span class="line"><span>void print_sum(int a, int b) {</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, a + b);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Readable code explains itself.</p><h4 id="step-2-header-hygiene" tabindex="-1">Step 2. Header Hygiene <a class="header-anchor" href="#step-2-header-hygiene" aria-label="Permalink to &quot;Step 2. Header Hygiene&quot;">​</a></h4><ul><li>Each<code>.h</code> file must have an include guard:</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ifndef MATH_UTILS_H</span></span>
<span class="line"><span>#define MATH_UTILS_H</span></span>
<span class="line"><span>// declarations</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><ul><li>Headers should declare, not define.</li><li>No global variables unless justified.</li><li>Use<code>static inline</code> carefully (for small utilities only).</li></ul><h4 id="step-3-memory-safety" tabindex="-1">Step 3. Memory Safety <a class="header-anchor" href="#step-3-memory-safety" aria-label="Permalink to &quot;Step 3. Memory Safety&quot;">​</a></h4><ul><li>Every<code>malloc</code> must have a corresponding<code>free</code>.</li><li>Check all allocation results:</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>p = malloc(size);</span></span>
<span class="line"><span>if (!p) { perror(&quot;malloc&quot;); exit(1); }</span></span></code></pre></div><ul><li>Avoid dangling pointers:</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>free(p);</span></span>
<span class="line"><span>p = NULL;</span></span></code></pre></div><ul><li>Use Valgrind or AddressSanitizer to ensure no leaks.</li></ul><h4 id="step-4-pointer-discipline" tabindex="-1">Step 4. Pointer Discipline <a class="header-anchor" href="#step-4-pointer-discipline" aria-label="Permalink to &quot;Step 4. Pointer Discipline&quot;">​</a></h4><ul><li>Check for null pointers before dereferencing.</li><li>Don’t return pointers to local variables:</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int* bad(void) {</span></span>
<span class="line"><span>    int x = 10;</span></span>
<span class="line"><span>    return &amp;x; // wrong: stack memory</span></span>
<span class="line"><span>}</span></span></code></pre></div><ul><li>Document ownership: who allocates, who frees.</li></ul><h4 id="step-5-error-handling" tabindex="-1">Step 5. Error Handling <a class="header-anchor" href="#step-5-error-handling" aria-label="Permalink to &quot;Step 5. Error Handling&quot;">​</a></h4><ul><li>Always check function return values:</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if (fwrite(buf, 1, len, file) != len) {</span></span>
<span class="line"><span>    perror(&quot;fwrite&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><ul><li>Use meaningful error messages.</li><li>Prefer returning error codes over silently ignoring failures.</li><li>For libraries, use<code>errno</code> or your own error enums.</li></ul><h4 id="step-6-undefined-behavior-prevention" tabindex="-1">Step 6. Undefined Behavior Prevention <a class="header-anchor" href="#step-6-undefined-behavior-prevention" aria-label="Permalink to &quot;Step 6. Undefined Behavior Prevention&quot;">​</a></h4><ul><li>No uninitialized variables.</li><li>No out-of-bounds array access.</li><li>No signed integer overflow.</li><li>No use-after-free.</li><li>Compile with:</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -Wall -Wextra -Wpedantic -fsanitize=undefined,address</span></span></code></pre></div><p>Fix all warnings, treat them as errors.</p><h4 id="step-7-portability" tabindex="-1">Step 7. Portability <a class="header-anchor" href="#step-7-portability" aria-label="Permalink to &quot;Step 7. Portability&quot;">​</a></h4><ul><li>Don’t assume<code>int</code> is 32 bits or<code>char</code> is signed.</li><li>Use<code>&lt;stdint.h&gt;</code> types (<code>int32_t</code>,<code>uint64_t</code>).</li><li>Use<code>size_t</code> for sizes and indexing.</li><li>Avoid platform-specific APIs unless wrapped.</li><li>Test on multiple compilers (<code>gcc</code>,<code>clang</code>,<code>tinycc</code>).</li></ul><h4 id="step-8-testing-and-validation" tabindex="-1">Step 8. Testing and Validation <a class="header-anchor" href="#step-8-testing-and-validation" aria-label="Permalink to &quot;Step 8. Testing and Validation&quot;">​</a></h4><ul><li>Every function that can fail must have at least one test.</li><li>Edge cases: empty input, zero values, large input.</li><li>Tests should run automatically:</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make test</span></span></code></pre></div><ul><li>Compare results with known-good output.</li><li>Document how to reproduce test results.</li></ul><h4 id="step-9-documentation" tabindex="-1">Step 9. Documentation <a class="header-anchor" href="#step-9-documentation" aria-label="Permalink to &quot;Step 9. Documentation&quot;">​</a></h4><ul><li>Add a short header to every file:</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/* math_utils.c</span></span>
<span class="line"><span> * Simple math helpers.</span></span>
<span class="line"><span> * Author: Your Name</span></span>
<span class="line"><span> * License: MIT</span></span>
<span class="line"><span> */</span></span></code></pre></div><ul><li>Comment tricky code, but not the obvious.</li><li>Maintain a<code>README.md</code> explaining build and run steps.</li><li>Version your code (Git). Write meaningful commit messages.</li></ul><h4 id="step-10-tiny-code-applying-the-checklist" tabindex="-1">Step 10. Tiny Code: Applying the Checklist <a class="header-anchor" href="#step-10-tiny-code-applying-the-checklist" aria-label="Permalink to &quot;Step 10. Tiny Code: Applying the Checklist&quot;">​</a></h4><p>Let’s check a small example:</p><p>Original:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int *make_array(int n){</span></span>
<span class="line"><span>  int arr[n]; for(int i=0;i&lt;n;i++) arr[i]=i; return arr;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Review notes:</p><ul><li>Returns pointer to local array → UB</li><li>Magic loop style → unreadable</li><li>Missing input validation</li></ul><p>Fixed:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int *make_array(int n) {</span></span>
<span class="line"><span>    if (n &lt;= 0) return NULL;</span></span>
<span class="line"><span>    int *arr = malloc(n * sizeof(int));</span></span>
<span class="line"><span>    if (!arr) { perror(&quot;malloc&quot;); return NULL; }</span></span>
<span class="line"><span>    for (int i = 0; i &lt; n; i++) arr[i] = i;</span></span>
<span class="line"><span>    return arr;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Passes checklist ✅</p><ul><li>Safe, clear, and portable.</li></ul><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>A checklist builds discipline and consistency. It ensures:</p><ul><li>Clean, maintainable code.</li><li>Fewer crashes and leaks.</li><li>Easier debugging and onboarding.</li><li>Long-term stability in complex systems.</li></ul><p>Every high-quality C project uses one, from open-source libraries to kernels.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Take one of your old C programs and review it using this checklist.</li><li>Fix memory leaks, add error checks, clean up naming.</li><li>Compile with all warnings on.</li><li>Run it through AddressSanitizer or Valgrind.</li><li>Document everything, then repeat for your next project.</li></ol><p>Next, you’ll wrap up this debugging chapter with a hands-on practice session: fixing real memory and logic bugs step by step.</p>`,57)])])}const g=a(t,[["render",l]]);export{h as __pageData,g as default};
